import runningRaces from "./running-races.json";

// Generated by scripts/build-race-maps.py from Garmin FIT files
export type RunningRace = {
  slug: string;
  title: string;
  category: string;
  date: string;
  startTime: string;
  location: string;
  garminActivityId: number;
  map: {
    src: string;
    width: number;
    height: number;
    zoom: number;
    /** Route in map-image pixel coordinates */
    route: [number, number][];
  };
  stats: {
    distanceKm: number;
    movingTimeSec: number;
    elapsedTimeSec: number;
    avgPaceSecPerKm: number;
    avgHeartRate: number | null;
    maxHeartRate: number | null;
    avgCadenceSpm: number | null;
    calories: number | null;
    splitsSecPerKm: number[];
  };
};

// Each hobby type carries its own item shape; add new variants to this union
export type Hobby = {
  type: "running";
  title: string;
  tagline: string;
  items: RunningRace[];
};

export const hobbies: Hobby[] = [
  {
    type: "running",
    title: "Running",
    tagline: "Race days, mapped from my Garmin.",
    // Newest race first
    items: [...(runningRaces as RunningRace[])].sort((a, b) => b.date.localeCompare(a.date)),
  },
];
